import sys
lines = sys.stdin.read().splitlines()
if lines:
    parts = lines[0].split()
    n, m, k = int(parts[0]), int(parts[1]), int(parts[2])
    adj = [[] for _ in range(n)]
    for line in lines[1:1+m]:
        uv = [int(x) for x in line.split()]
        if len(uv) == 2:
            adj[uv[0]].append(uv[1]); adj[uv[1]].append(uv[0])
    restr = set([int(x) for x in lines[1+m].split()]) if k > 0 and len(lines) > 1+m else set()
    from collections import deque
    q = deque([0])
    visited = {0}
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in visited and v not in restr:
                visited.add(v)
                q.append(v)
    print(len(visited))
